<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notificações</title><link rel="stylesheet" href="<?=URL?>/public/css/notificacoes_user.css"></head><body><?php include APP.'/Views/usuarios/menu_user.php'; ?><main class="container"><h1>Notificações</h1><?php if(empty($notificacoes)): ?><p>Você não possui notificações.</p><?php else: foreach($notificacoes as $n): ?><article class="notificacao"><h3><?=htmlspecialchars($n->noti_titulo,ENT_QUOTES)?></h3><p><?=htmlspecialchars($n->noti_mensagem,ENT_QUOTES)?></p><small><?=htmlspecialchars($n->noti_data_hora,ENT_QUOTES)?></small><form method="POST" action="<?=URL?>/usuarios/notificacoes_user"><input type="hidden" name="csrf" value="<?=htmlspecialchars(Seguranca::token(),ENT_QUOTES)?>"><input type="hidden" name="notificacao" value="<?= (int)$n->noti_id ?>"><button>Marcar como lida</button></form></article><?php endforeach;endif; ?></main><?php include APP.'/Views/usuarios/footer_user.php'; ?></body></html>